-- Attach all verified Dutch supplier keys to the canonical supplier "Голландия".
-- Source SHA-256: ce5b6ee3177bc29f95423db188f95bc4eed91bd52b416b8c7c0fff1a9c9dd4c4

-- Keep the existing supplier ID whenever possible so historical documents,
-- orders and manually confirmed aliases remain attached without a rewrite.
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM procurement_suppliers WHERE LOWER(name) = LOWER('Gale ProWay')
  ) AND NOT EXISTS (
    SELECT 1 FROM procurement_suppliers WHERE LOWER(name) = LOWER('Голландия')
  ) THEN
    UPDATE procurement_suppliers
    SET name = 'Голландия', kind = 'international', country_code = 'NL',
      default_currency = 'EUR', active = TRUE, updated_at = CURRENT_TIMESTAMP
    WHERE LOWER(name) = LOWER('Gale ProWay');
  ELSE
    INSERT INTO procurement_suppliers (name, kind, country_code, default_currency)
    SELECT 'Голландия', 'international', 'NL', 'EUR'
    WHERE NOT EXISTS (
      SELECT 1 FROM procurement_suppliers WHERE LOWER(name) = LOWER('Голландия')
    );
  END IF;
END $$;

CREATE TEMP TABLE procurement_holland_import (
  supplier_name TEXT NOT NULL,
  raw_name TEXT NOT NULL,
  normalized_name TEXT NOT NULL,
  pot_diameter_cm NUMERIC(8,2),
  height_cm NUMERIC(8,2),
  saby_id TEXT,
  match_status TEXT NOT NULL,
  occurrences INTEGER NOT NULL,
  last_seen_at DATE
) ON COMMIT DROP;

