INSERT INTO saby_nomenclature (saby_id, code, name)
SELECT DISTINCT imported.saby_id, imported.saby_id, imported.normalized_name
FROM procurement_holland_import imported
WHERE imported.match_status = 'confirmed' AND imported.saby_id IS NOT NULL
ON CONFLICT (saby_id) DO NOTHING;

INSERT INTO procurement_supplier_aliases (
  supplier_id, raw_name, normalized_name, supplier_article,
  pot_diameter_cm, height_cm, matched_saby_id, match_status,
  confidence, availability_status, occurrences, last_seen_at
)
SELECT supplier.id, imported.raw_name, imported.normalized_name, '',
  imported.pot_diameter_cm, imported.height_cm, imported.saby_id, imported.match_status,
  CASE WHEN imported.match_status IN ('confirmed', 'ignored') THEN 1 ELSE 0 END,
  'unknown', imported.occurrences, imported.last_seen_at
FROM procurement_holland_import imported
JOIN procurement_suppliers supplier ON LOWER(supplier.name) = LOWER(imported.supplier_name)
ON CONFLICT DO NOTHING;

INSERT INTO procurement_supplier_products (
  supplier_id, saby_id, supplier_article, availability_status
)
SELECT DISTINCT supplier.id, imported.saby_id, '', 'unknown'
FROM procurement_holland_import imported
JOIN procurement_suppliers supplier ON LOWER(supplier.name) = LOWER(imported.supplier_name)
WHERE imported.match_status = 'confirmed'
ON CONFLICT (supplier_id, saby_id) DO NOTHING;

-- If Gale survived the guarded removal because it has history, preserve that
-- history under "Голландия" and then remove the obsolete supplier record.
UPDATE procurement_order_lines line SET supplier_alias_id = replacement.id
FROM procurement_supplier_aliases previous
JOIN procurement_suppliers old_supplier ON old_supplier.id = previous.supplier_id
JOIN procurement_suppliers new_supplier ON LOWER(new_supplier.name) = LOWER('Голландия')
JOIN procurement_supplier_aliases replacement ON replacement.supplier_id = new_supplier.id
  AND LOWER(replacement.raw_name) = LOWER(previous.raw_name)
  AND COALESCE(replacement.supplier_article, '') = COALESCE(previous.supplier_article, '')
  AND COALESCE(replacement.pot_diameter_cm, -1) = COALESCE(previous.pot_diameter_cm, -1)
  AND COALESCE(replacement.height_cm, -1) = COALESCE(previous.height_cm, -1)
WHERE line.supplier_alias_id = previous.id
  AND LOWER(old_supplier.name) = LOWER('Gale ProWay');

UPDATE procurement_orders orders SET supplier_id = holland.id
FROM procurement_suppliers gale, procurement_suppliers holland
WHERE orders.supplier_id = gale.id
  AND LOWER(gale.name) = LOWER('Gale ProWay')
  AND LOWER(holland.name) = LOWER('Голландия');

UPDATE procurement_documents documents SET supplier_id = holland.id
FROM procurement_suppliers gale, procurement_suppliers holland
WHERE documents.supplier_id = gale.id
  AND LOWER(gale.name) = LOWER('Gale ProWay')
  AND LOWER(holland.name) = LOWER('Голландия');

DELETE FROM procurement_suppliers WHERE LOWER(name) = LOWER('Gale ProWay');
